    return clone_repo(clone_url, repo_dir, repo, logger=logger)


def clone_repo_with_fork(clone_url: str, repo_dir: str, repo_name: str,
                          upstream_url: str, logger=None) -> Optional[str]:
    """克隆上游源仓库并将 fork 设为 origin 以便后续推送。

    AtomGit 的 fork 仓库 git 对象经常不可访问。策略：
    1. 从上游源仓库克隆完整内容
    2. 将 origin 重命名为 upstream
    3. 将 fork 设为 origin（step5 推送到 origin=fork）

    Args:
        clone_url: fork 仓库的 clone URL
        repo_dir: 本地仓库存放目录
        repo_name: 本地仓库目录名
        upstream_url: 上游源仓库的 clone URL
        logger: 日志实例

    Returns:
        成功返回本地仓库路径，失败返回 None
    """
    repo_path = os.path.join(repo_dir, repo_name)

    if os.path.exists(repo_path):
        if logger:
            logger.info(f"  仓库已存在: {repo_path}")
        return repo_path

    os.makedirs(repo_dir, exist_ok=True)

    if logger:
        logger.info(f"  克隆仓库（上游源）: {upstream_url}")
        logger.info(f"  将 fork 设为 origin: {clone_url}")

    for attempt in range(1, 3):
        result = subprocess.run(
            ['git', 'clone', upstream_url, repo_path],
            capture_output=True,
            text=True
        )

        if result.returncode == 0:
            check = subprocess.run(
                ['git', 'rev-parse', 'HEAD'],
                cwd=repo_path, capture_output=True, text=True
            )
            if check.returncode == 0 and check.stdout.strip():
                # 1. origin → upstream
                subprocess.run(
                    ['git', 'remote', 'rename', 'origin', 'upstream'],
                    cwd=repo_path, capture_output=True, text=True
                )
                if logger:
                    logger.info(f"  已将 origin 重命名为 upstream")

                # 2. 添加 fork 为 origin（用于后续推送）
                subprocess.run(
                    ['git', 'remote', 'add', 'origin', clone_url.rstrip('.git')],
                    cwd=repo_path, capture_output=True, text=True
                )
                if logger:
                    logger.info(f"  已添加 fork 作为 origin")

                # 3. 清理 origin/master 的 track 配置（它现在指向不存在的 fork branch）
                subprocess.run(
                    ['git', 'config', '--unset', 'branch.master.remote'],
                    cwd=repo_path, capture_output=True, text=True
                )
                subprocess.run(
                    ['git', 'config', '--unset', 'branch.master.merge'],
                    cwd=repo_path, capture_output=True, text=True
                )

                if logger:
                    logger.info(f"  克隆成功")

                return repo_path

        if attempt == 1:
            if logger:
                logger.warning(f"  克隆失败 - {result.stderr.strip()[:200]}")
                logger.info(f"  等待 30 秒后重试...")
            time.sleep(30)
            if logger:
                logger.info(f"  重试克隆: {upstream_url}")

    if logger:
        logger.error(f"  克隆失败 - {result.stderr.strip()[:200] if result else 'unknown'}")
        logger.error(f"  克隆失败，结束执行")
    return None


def download_patch(url: str, output_dir: str, cve_id: str, logger=None) -> Optional[str]:
    os.makedirs(output_dir, exist_ok=True)

    filename = f"backport-{cve_id}.patch"
    filepath = os.path.join(output_dir, filename)

    if os.path.exists(filepath):
        if logger:
            logger.info(f"      补丁已存在: {filename}")
        return filepath

    if logger:
        logger.info(f"      下载: {url}")

    req = urllib.request.Request(url, headers={'User-Agent': 'cve-deal/1.0'})

    try:
        with urllib.request.urlopen(req, timeout=60) as response:
            content = response.read()

            with open(filepath, 'wb') as f:
                f.write(content)

            if logger:
                logger.success(f"      下载成功: {filename}")
            return filepath
    except urllib.error.HTTPError as e:
        if logger:
            logger.error(f"      下载失败: {e.code} {e.reason}")
        return None
    except Exception as e:
        if logger:
            logger.error(f"      下载失败: {e}")
        return None
